// ones `tests/link/crypto_wycheproof/aes_gcm.ts` leaves out, and
// nish/crypto/aes must refuse each of their keys, since it does not offer
// AES-192. Every value kept is as upstream wrote it. `tests/link/crypto_aes`
// and `crypto_aes_f64` run them.


/** One Wycheproof AES-GCM case with a 192-bit key, its byte strings in lowercase hex as upstream writes them. */
export interface WycheproofAesGcm192Case {
  comment: string
  key: string
  iv: string
  aad: string
  msg: string
  ct: string
  tag: string
  /** A `number`, so the file compiles in either number mode: a bare literal in an object literal takes the mode's width. */
  tcId: number
  /** `"result": "valid"`; every other case in this file is `"invalid"`. */
  valid: boolean
}

/** How many cases this file keeps: every case of upstream's with a 192-bit key. */
export const WYCHEPROOF_AES_GCM_192_KEPT: i32 = 103

